import sys, json; sys.path.insert(0,'.')
from data import W
import numpy as np

def pts(cond):
    out=[]
    for k,w in sorted(W.items()):
        if w['cond']!=cond or w['excl']: continue
        v = w['v']*(2.0 if cond=='C7' else 1.0)   # Amber 1:1000 dilution -> x(1000/500)
        out.append((w['S'], v, k))
    return out

def sse(p, S, v):
    V,K=p
    return float(np.sum((v - V*S/(K+S))**2))

def fit_free(S,v):
    # Gauss-Newton / LM on (Vmax,Km)
    V,K=max(v),np.median(S)
    lam=1e-3
    for _ in range(500):
        f = V*S/(K+S)
        r = v-f
        J = np.column_stack([S/(K+S), -V*S/(K+S)**2])
        A = J.T@J; g = J.T@r
        step = np.linalg.solve(A+lam*np.diag(np.diag(A)), g)
        newp=(V+step[0], K+step[1])
        if newp[0]>0 and newp[1]>0 and sse(newp,S,v)<sse((V,K),S,v):
            V,K=newp; lam=max(lam/3,1e-9)
        else:
            lam*=5
        if lam>1e12: break
    return V,K

def fit_km_fixed_V(S,v,V):
    # 1-D minimise SSE over Km (golden section on log scale)
    f=lambda K: float(np.sum((v - V*S/(K+S))**2))
    a,b=np.log(1e-3),np.log(1e6)
    g=(np.sqrt(5)-1)/2
    c=b-g*(b-a); d=a+g*(b-a)
    for _ in range(300):
        if f(np.exp(c))<f(np.exp(d)): b=d
        else: a=c
        c=b-g*(b-a); d=a+g*(b-a)
    return float(np.exp((a+b)/2))

res={}
for cond in ['C3','C4','C5','C7','C8','C6','C1','C2']:
    P=pts(cond)
    S=np.array([p[0] for p in P],float); v=np.array([p[1] for p in P],float)
    if cond in ('C1','C6'):
        V=res['C3']['vmax']; K=fit_km_fixed_V(S,v,V)
    elif cond=='C2':
        V=res['C4']['vmax']; K=fit_km_fixed_V(S,v,V)
    else:
        V,K=fit_free(S,v)
    res[cond]=dict(vmax=float(V),km=float(K),n=len(P),
                   rms=float(np.sqrt(np.mean((v-V*S/(K+S))**2))))
    print(cond, 'n=',len(P), 'Vmax=%.4f Km=%.3f rms=%.4f'%(V,K,res[cond]['rms']))
json.dump(res,open('fit.json','w'),indent=1)

import sys,json; sys.path.insert(0,'.')
from fit import pts, res
import numpy as np
best={}
for c,fixedV in [('C3',None),('C4',None),('C5',None),('C7',None),('C8',None),('C6',res['C3']['vmax']),('C1',res['C3']['vmax']),('C2',res['C4']['vmax'])]:
    P=pts(c); S=np.array([p[0] for p in P],float); v=np.array([p[1] for p in P],float)
    Vs=np.linspace(res[c]['vmax']*0.9,res[c]['vmax']*1.1,401) if fixedV is None else np.array([fixedV])
    Ks=np.linspace(res[c]['km']*0.9,res[c]['km']*1.1,401)
    bestv=(1e99,None,None)
    for V in Vs:
        sse=((v[None,:]-V*S[None,:]/(Ks[:,None]+S[None,:]))**2).sum(1)
        i=sse.argmin()
        if sse[i]<bestv[0]: bestv=(sse[i],V,Ks[i])
    print(c,'grid best Vmax=%.4f Km=%.2f | LM Vmax=%.4f Km=%.2f'%(bestv[1],bestv[2],res[c]['vmax'],res[c]['km']))

